/**
 * Vampire drain is a separate maximum-tower-health channel, not regular attack.
 * Enemy Attack labs, defense, wall and Energy Shield must not scale this rate.
 * Public mechanic reference (not a recovered native timing implementation):
 * https://the-tower-idle-tower-defense.fandom.com/wiki/Enemies#Vampire
 * Garlic's lab value is a percentage of Thorn Damage per active beam second:
 * https://the-tower-idle-tower-defense.fandom.com/wiki/Lab/Garlic_Thorns
 */
export const VAMPIRE_DRAIN_MAX_TOWER_HEALTH_FRACTION_PER_SECOND = 0.02

/** Linear max-enemy-HP fraction per second; neither a kill hazard nor current HP. */
export function vampireGarlicMaxHealthDamageRate(thornsFraction: number, garlicLabPercent: number): number {
  if (![thornsFraction, garlicLabPercent].every(value => Number.isFinite(value) && value >= 0))
    throw new Error('VAMPIRE_GARLIC_FINITE_NONNEGATIVE_COEFFICIENT_REQUIRED')
  const result = thornsFraction * garlicLabPercent / 100
  if (!Number.isFinite(result)) throw new Error('VAMPIRE_GARLIC_COEFFICIENT_OVERFLOW')
  return result
}
